// ===============================================================================
// DAEMIND SRE - FILTRO DE MENSAGEM DE ÁUDIO DO CHATWOOT / EVOLUTION
// ===============================================================================
const body = $json.body || $json;

const conversationId = body.conversation?.id || body.conversation_id || 1;
const accountId = body.account?.id || body.account_id || 1;
const attachments = body.attachments || [];
const isAudio = attachments.some(a => a.file_type === 'audio') || Boolean(body.data?.message?.audioMessage);
const audioUrl = attachments[0]?.data_url || body.data?.message?.mediaUrl || '';
const senderName = body.sender?.name || body.data?.pushName || 'Cliente';

return [{
  json: {
    conversation_id: conversationId,
    account_id: accountId,
    is_audio: isAudio,
    audio_url: audioUrl,
    sender_name: senderName
  }
}];

