// ===============================================================================
// DAEMIND SRE - FORMATAÇÃO DE NOTA PRIVADA INTERNA
// ===============================================================================
const rawContent = $json.choices?.[0]?.message?.content || '{}';
let parsed = {};
try {
  const cleanJson = rawContent.replace(/```json\n?|```/g, '').trim();
  parsed = JSON.parse(cleanJson);
} catch (e) {
  parsed = {
    sentimento: 'NEUTRO',
    resumo_pontos_chave: 'Áudio recebido do cliente.',
    acao_recomendada: 'Ouvir o áudio e responder.'
  };
}

const emojiSentimento = parsed.sentimento === 'IRRITADO_URGENTE' ? '🚨' : parsed.sentimento === 'SATISFEITO' ? '🟢' : '🟡';

const notaPrivada = `🤖 **DAEMIND AI COPILOT - RESUMO DE ÁUDIO**\n\n${emojiSentimento} **Sentimento:** ${parsed.sentimento}\n📝 **Resumo:** ${parsed.resumo_pontos_chave}\n💡 **Ação Recomendada:** ${parsed.acao_recomendada}`;

return [{
  json: {
    ...parsed,
    nota_privada_texto: notaPrivada,
    account_id: $('Detectar Áudio').item.json.account_id,
    conversation_id: $('Detectar Áudio').item.json.conversation_id
  }
}];
